// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/faultlines/{faultlineId}/blast-radius", wrapper.GetBlastRadius)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/findings", wrapper.GetFindingByKey)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/findings/{id}", wrapper.GetFinding)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/findings/{id}/archive", wrapper.ArchiveFinding)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/findings/{id}/assessment", wrapper.GetFindingAssessment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/findings/{id}/commissions", wrapper.CommissionFinding)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/findings/{id}/commissions/{commissionId}/withdraw", wrapper.WithdrawCommission)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/findings/{id}/position", wrapper.GetPosition)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/findings/{id}/proposals", wrapper.RaiseProposal)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/findings/{id}/proposals/{proposalId}/accept", wrapper.AcceptProposal)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/findings/{id}/proposals/{proposalId}/reject", wrapper.RejectProposal)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/findings/{id}/recommend", wrapper.RecommendPosition)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/findings/{id}/reopen", wrapper.ReopenFinding)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/findings/{id}/resolve", wrapper.ResolveFinding)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/releases/{releaseId}/compare/{candidateId}", wrapper.CompareReleases)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/releases/{releaseId}/posture", wrapper.GetReleasePosture)
	})

	return r
}

